                '{tribute} works the vine tangle of {zone}, carefully, and comes away with {item}.',
                '{tribute} strips a bunker in {zone} of what\'s left and finds {item}.',
                '{tribute} digs at the crater rim of {zone} and turns up {item}.',
                '{tribute} works the root mat of {zone} on their knees, testing every handful, and finds {item}.',
