// §1 (requests): the five new arenas' packs, folded in before the extra-event
// merge below so they are subject to exactly the same passes as every other
// hand-authored pack — the shared pool, the derived ids, the coverage scripts.
Object.assign(ARENA_FLAVOR, NEW_ARENA_FLAVOR);

// §7.4: fold the per-group extra event files into the authored packs once,
// at load, so every reader of `ARENA_FLAVOR[id].events` (the picker, the
// achievements, the coverage scripts) sees one pool.
for (const [id, events] of Object.entries(EXTRA_ARENA_EVENTS)) {
    const pack = ARENA_FLAVOR[id];
    if (pack) pack.events = [...pack.events, ...events];
}

/**
 * Audit 3 §1.4: every arena event gets a stable id, derived rather than typed.
 *
 * `id` was documented as optional because "the great majority of events are
 * anonymous and stay that way" — and 1,123 of the 1,323 authored events took
 * that option. The consequences were all silent:
 *
 *   - `oncePerRun` keys on `firedEvents`, which keys on id, so an anonymous
 *     event could not be once-per-run however it was tagged.
 *   - `eventLastFired` is the cooldown, so the same set piece could land twice
 *     in three cycles.
 *   - Nothing could *count* them. `test:flavor` measures pool depth and has no
 *     way to ask whether a given event has ever reached a player, which is the
 *     question that actually matters for the largest content table in the
 *     repository. Answering it once took a throwaway script that matched log
 *     text against event templates by longest literal substring.
 *
 * Deriving the id here rather than hand-writing 1,123 of them keeps the source
 * tables readable, and makes the id impossible to forget on a new event. The
 * slug is taken from the text because the text is the thing that is actually
 * unique; a collision would mean two events with the same opening, which is a
 * content bug worth failing on, so `validate-arenas` asserts against it.
 */
export function derivedEventId(arenaId: string, text: string, index: number): string {
    const slug = text
        .toLowerCase()
        .replace(/\{[a-z]+\}/g, ' ')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .split('-')
        .filter(Boolean)
        .slice(0, 8)
        .join('-');
    return `${arenaId}-${slug || `event-${index}`}`;
}

/**
 * Events whose opening words slug to the same thing. Deterministic given the
 * table order, and reported by `validate-arenas` so a genuine near-duplicate
 * is visible rather than silently suffixed forever.
 */
export const DERIVED_ID_COLLISIONS: string[] = [];

function stampEventIds(arenaId: string, events: ArenaEventDef[]) {
    const taken = new Set(events.map(e => e.id).filter((x): x is string => x !== undefined));
    events.forEach((e, i) => {
        // A hand-written id wins: `chain` and the once-per-run packs refer to
        // those by name from other files.
        if (e.id) return;
        const base = derivedEventId(arenaId, e.text, i);
        let id = base;
        for (let n = 2; taken.has(id); n++) {
            id = `${base}-${n}`;
            if (n === 2) DERIVED_ID_COLLISIONS.push(base);
        }
        taken.add(id);
        e.id = id;
    });
}

for (const [id, pack] of Object.entries(ARENA_FLAVOR)) stampEventIds(id, pack.events);
for (const [id, pack] of Object.entries(PROCEDURAL_FLAVOR_PACKS)) stampEventIds(id, pack.events);
stampEventIds('generic', GENERIC_ARENA_FLAVOR.events);
stampEventIds('universal', UNIVERSAL_EVENTS);

export function arenaFlavor(arenaId: string, arena?: Arena): ArenaFlavor {
    // A procedural arena has no hand-authored entry here — it used to fall
    // back to one of four fixed pre-written packs, so every rainforest arena
    // read as the same rainforest regardless of the zones it actually rolled.
    // `proceduralArenaFlavor` composes flavour from the tags the generated
    // arena's zones actually carry.
    if (arena && arenaId.startsWith('procedural-')) return withUniversalEvents(proceduralArenaFlavor(arena));
    return withUniversalEvents(ARENA_FLAVOR[arenaId] ?? PROCEDURAL_FLAVOR_PACKS[arenaId] ?? GENERIC_ARENA_FLAVOR);
}

/**
 * A1: reads an action pool with a fallback.
 *
 * The four stance pools added with the extended stance roster are optional per
 * arena — twenty-eight arenas times four pools is a lot of prose to gate the
 * mechanic behind. An arena that authors its own wins; everything else falls
 * back to the terrain-general generic set, which is written to work on ground
 * the author has never seen.
 */
export function actionPool(flavor: ArenaFlavor, key: ArenaActionKey): string[] {
    const authored = flavor.actions[key];
    const generic = GENERIC_ACTIONS[key] ?? GENERIC_ACTIONS.rest;
    if (!authored || authored.length === 0) return generic;

    // §5: an authored pool used to *replace* the generic one outright, which
    // made a short authored pool actively worse than none at all — the four
    // conditional-stance pools are authored at four entries against a generic
    // twelve, so seventeen arenas were repeating themselves four ways round
    // in their own voice instead of twelve ways round in a shared one. They
    // are merged instead: the arena's own lines are what the arena sounds
    // like, so they are weighted to lead, and the generic pool is what stops
    // a run of nine days sounding like a loop.
    const target = Math.max(GENERIC_ACTION_TARGET, authored.length);
    if (authored.length >= target) return authored;
    const filler = generic.filter(line => !authored.includes(line));
    return [...authored, ...authored, ...filler];
}

/**
 * §5: pool size at which an authored set stands on its own. Below it the
 * generic pool is merged in behind it rather than discarded.
 */
const GENERIC_ACTION_TARGET = 8;

/**
 * §1.3: how much of the pool the shared universal events are allowed to be.
 *
 * `withUniversalEvents` appended fourteen universal events to per-arena packs
 * of five to twelve and the picker drew uniformly, so the five sparsest arenas
 * (seapeaks, craterfield, burnscar, canopyweb, acousticforest) drew a generic
 * event roughly three times in four — which is most of why they read
 * interchangeably. The universal pool is now weighted down to a ~30% share
 * regardless of how many authored events an arena has, so a thin arena is
 * repetitive in its own voice rather than in nobody's.
 */
export const UNIVERSAL_EVENT_SHARE = 0.3;

/** Merges the shared event pool into an arena's authored one. Never mutates the source. */
function withUniversalEvents(flavor: ArenaFlavor): ArenaFlavor {
    const authoredWeight = flavor.events.reduce((sum, e) => sum + (e.weight ?? 1), 0) || 1;
    // Solve `u / (authored + u) = share` for the total weight the universal
    // pool should carry, then split it evenly across its members.
    const universalTotal = authoredWeight * UNIVERSAL_EVENT_SHARE / (1 - UNIVERSAL_EVENT_SHARE);
    // §7.1: scaled *proportionally*, not flattened. This used to assign every
    // universal event the same weight, which silently threw away the relative
    // weights the pool itself authors — the load-bearing collapse asks for 1.4
    // and the bleakest one-offs ask for less, and all of them were being
    // levelled to the same number. The share the pool takes overall is
    // unchanged; what changes is that a weight written in the table now means
    // something.
    const universalWeight = UNIVERSAL_EVENTS.reduce((sum, e) => sum + (e.weight ?? 1), 0) || 1;
    const scale = universalTotal / universalWeight;
    return {
        ...flavor,
        events: [...flavor.events, ...UNIVERSAL_EVENTS.map(e => ({ ...e, weight: (e.weight ?? 1) * scale }))],
    };
}
